#!/bin/sh
# Build and run the sb_dbus micro-benchmark (tools/dbus_bench.c).
# Usage: tools/dbus_bench.sh   (CC overrides the compiler)
set -eu

here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
root=$(dirname "$here")
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# Minimal feature-probe config (normally generated by the CMake build).
mkdir -p "$work/shrewd-basic/config"
cat > "$work/shrewd-basic/config/config.h" <<'CFG'
#ifndef SHREWD_BASIC_CONFIG_H
#define SHREWD_BASIC_CONFIG_H
#define SHREWD_BASIC_FORMAT_JSON 1
#define SHREWD_BASIC_FORMAT_BIN 1
#define SHREWD_BASIC_FORMAT_INI 1
#define SHREWD_BASIC_FORMAT_ENV 1
#define SHREWD_BASIC_FORMAT_CSV 1
#define SHREWD_BASIC_FORMAT_TOML 1
#define SHREWD_BASIC_FORMAT_MSGPACK 1
#define SHREWD_BASIC_FORMAT_CBOR 1
#endif
CFG

${CC:-cc} -std=c11 -O2 \
    -I"$root/include" -I"$root/include/shrewd-basic-internal" \
    -I"$work" -pthread \
    "$here/dbus_bench.c" \
    "$root"/library/dbus/*.c \
    "$root"/library/reflect/*.c \
    "$root"/library/json/*.c \
    "$root"/library/ds/*.c \
    "$root"/library/log/log.c \
    "$root"/library/platform/error.c "$root"/library/platform/memory.c \
    -o "$work/dbus_bench"

"$work/dbus_bench"
